-- ============================================================
-- Aloudata API 端点配置：含请求/响应参数规范
-- ============================================================
-- API 版本升级时，只需修改 aloudata.api.endpoints 和 aloudata.api.version 的值即可，
-- 无需改动代码。端点配置为 JSON 格式，包含端点名称、所属服务、路径、HTTP 方法、描述，
-- 以及完整的 requestParams 和 responseParams 参数规范定义。
--
-- 归因分析 endpoint 配置严格按官方文档补全（官方无 attribution_breakdown 接口）：
--   1. attribution_check：analysisRange 结构（current/comparison 日期）+ responseParams
--   2. attribution_multi_dim：attributionRange 结构 + orders 排序字段 + responseParams
--   3. attribution_drilldown：同 multi_dim 但 dimension 单数 + filters 含下钻值筛选
--   4. attribution_tree：按官方文档结构 metricTree + metrics + attributionRange
-- 注意：代码 AloudataServiceImpl.ATTRIBUTION_BREAKDOWN_ENDPOINT 引用的 attribution_breakdown
-- 在官方文档中不存在，本配置不包含该 endpoint；如需启用需另行确认其真实接口路径。
--
-- 参数规范说明：
-- - name: 参数名称
-- - type: 数据类型（String/Integer/Long/Boolean/Array/Map/Object）
-- - required: 是否必填
-- - defaultValue: 默认值（字符串表示）
-- - description: 参数说明
-- - paramLocation: 传递方式（HEADER/PATH/QUERY/BODY），仅请求参数适用
-- - enumValues: 可选取值范围（逗号分隔）

INSERT INTO mate_system_setting (id, setting_key, setting_value, description, create_time, update_time)
VALUES
  (2001, 'aloudata.api.version', 'v1', 'Aloudata API 版本号', NOW(), NOW())
ON CONFLICT (id) DO UPDATE SET
    setting_value = EXCLUDED.setting_value,
    update_time = NOW();

INSERT INTO mate_system_setting (id, setting_key, setting_value, description, create_time, update_time)
VALUES
  (2002, 'aloudata.api.endpoints', '{"metrics_query":{"service":"semantic","path":"/semantic/api/v1.1/metrics/query","method":"POST","description":"通过指标查询API，用户可以查询已经完成定义的指标的结果值，并在查询过程中临时为指标添加时间限定、业务限定、快速衍生（计算同环比、计算占比、计算排名）以及控制查询中指标的受影响维度，查询其指标结果值","requestParams":[{"name":"tenant-id","type":"String","required":true,"description":"租户ID，指标平台为多租户架构，查询时需要指明资产所在的租户","paramLocation":"HEADER"},{"name":"auth-type","type":"String","required":true,"description":"认证方式","paramLocation":"HEADER","enumValues":"UID,TOKEN,ACCOUNT,APIKEY"},{"name":"auth-value","type":"String","required":true,"description":"与 auth-type 对应的认证值","paramLocation":"HEADER"},{"name":"query-user-account","type":"String","required":false,"description":"鉴权用户。使用该用户进行鉴权处理，若为空则使用 auth-value 对应的用户进行鉴权","paramLocation":"HEADER"},{"name":"metrics","type":"Array","required":true,"description":"查询指标，支持使用指标平台已经定义的指标，支持使用 metricDefinitions 中临时定义的指标以及通过快速计算能力进行扩展的指标","paramLocation":"BODY"},{"name":"metricDefinitions","type":"Map","required":false,"description":"临时指标在查询中基于已定义的指标临时进行定义，而生成的临时指标","paramLocation":"BODY"},{"name":"dimensions","type":"Array","required":false,"description":"查询维度支持使用已经定义的维度支持对日期类型的维度进行快速粒度切换","paramLocation":"BODY"},{"name":"filters","type":"Array","required":false,"description":"全局筛选对当前查询中的全部指标，都进行维度上的数据过滤","paramLocation":"BODY"},{"name":"specialMvConfig","type":"Map","required":false,"description":"用于配置查询时是否启用指定物化表加速，以及如何处理物化表未命中的情况","paramLocation":"BODY"},{"name":"resultFilters","type":"Array","required":false,"description":"结果筛选对查询结果进行筛选，可以选去指标或者维度","paramLocation":"BODY"},{"name":"timeConstraint","type":"String","required":false,"description":"指标日期范围查询指标数据的指标日期范围","paramLocation":"BODY"},{"name":"orders","type":"Array","required":false,"description":"排序将查询的结果按照指定的顺序排序返回，排序的内容需要包含在 metric 或 dimensions 中","paramLocation":"BODY"},{"name":"limit","type":"int","required":false,"defaultValue":100,"description":"返回结果的条数","paramLocation":"BODY"},{"name":"offset","type":"int","required":false,"